import React from 'react';
import { Bell, ShieldCheck } from 'lucide-react';
import { useSocket } from '../context/SocketContext';

export default function Navbar() {
  const { newOrderAlert, setNewOrderAlert } = useSocket();

  return (
    <header className="h-16 bg-white border-b border-emerald-100 flex items-center justify-between px-8 shadow-sm">
      <div className="flex items-center gap-4">
        {newOrderAlert && (
          <div className="flex items-center gap-2 bg-emerald-100 text-emerald-800 px-3 py-1.5 rounded-full text-xs font-bold animate-bounce shadow-sm">
            <span>🚨 নতুন অর্ডার #{newOrderAlert.order_id || 'Alert'}!</span>
            <button
              onClick={() => setNewOrderAlert(null)}
              className="text-emerald-600 hover:text-emerald-900 ml-1 font-black"
            >
              ✕
            </button>
          </div>
        )}
      </div>

      <div className="flex items-center gap-5">
        <button className="relative p-2 text-gray-500 hover:text-emerald-600 rounded-full hover:bg-emerald-50 transition-colors">
          <Bell className="w-5 h-5" />
          <span className="absolute top-1 right-1 w-2 h-2 bg-emerald-500 rounded-full ring-2 ring-white"></span>
        </button>

        <div className="flex items-center gap-3 pl-4 border-l border-gray-200">
          <div className="text-right">
            <p className="text-sm font-bold text-gray-800">Super Admin</p>
            <p className="text-xs text-emerald-600 font-medium">Head Office</p>
          </div>
          <div className="w-9 h-9 rounded-full bg-emerald-600 text-white flex items-center justify-center font-bold shadow-md shadow-emerald-600/20">
            <ShieldCheck className="w-5 h-5" />
          </div>
        </div>
      </div>
    </header>
  );
}
